-- Số tự tăng tiếp tục sau id lớn nhất
select setval(pg_get_serial_sequence('menu_categories', 'id'), (select max(id) from menu_categories));
select setval(pg_get_serial_sequence('option_groups', 'id'), (select max(id) from option_groups));
select setval(pg_get_serial_sequence('option_choices', 'id'), (select max(id) from option_choices));

-- Gắn lại món trong ưu đãi thử và trong đơn đang mở theo tên món
insert into promotion_items (promotion_id, part, menu_item_id, qty, sort_order)
  select distinct on (x.promotion_id, x.part, mi.id) x.promotion_id, x.part, mi.id, x.qty, x.sort_order
    from _pi x join menu_items mi on mi.name = x.name
  on conflict do nothing;
update order_items oi set menu_item_id = mi.id
  from menu_items mi where oi.menu_item_id is null and mi.name = oi.item_name;

commit;

select (select count(*) from menu_categories) as danh_muc, (select count(*) from menu_items) as mon,
       (select count(*) from option_groups) as nhom_tuy_chon, (select count(*) from option_choices) as lua_chon,
       (select count(*) from menu_item_option_groups) as lien_ket;
